#include <iostream>
#include <string>
#include <cstdio>

int main() {
    // Demo legacy C scanf semantics
    double d1 = 0.0, d2 = 0.0;
    char singleChar = '\0';
    char buffer[9] = {0}; // Holds 8 chars + null

    // Simulated input parsed via sscanf
    const char* legacyInput = "3.14159 1.5e+02 S Sunday";
    std::sscanf(legacyInput, "%lf %le %c %8s", &d1, &d2, &singleChar, buffer);
    std::printf("Legacy C Scanf:\n");
    std::printf("d1: %f, d2: %f, char: '%c', str: \"%s\"\n", d1, d2, singleChar, buffer);

    // C++17 type-safe equivalent with std::cin/iostreams
    std::cout << "\nModern C++17 equivalent:\n";
    double cpp_d1 = 0.0, cpp_d2 = 0.0;
    char cpp_c = '\0';
    std::string cpp_s;

    if (std::cin >> cpp_d1 >> cpp_d2 >> cpp_c >> cpp_s) {
        std::cout << "Read: " << cpp_d1 << ", " << cpp_d2 
                  << ", '" << cpp_c << "', \"" << cpp_s << "\"\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <cstdio>

int main() {
    // 1. Scan set and inverted scan set demonstration
    char vowels[16] = {0};
    char consonants[16] = {0};
    const char* text1 = "ooeeooahah";
    const char* text2 = "String";

    std::sscanf(text1, "%15[aeiou]", vowels);
    std::sscanf(text2, "%15[^aeiou]", consonants);

    std::printf("Scan set [aeiou] on \"%s\": \"%s\"\n", text1, vowels);
    std::printf("Inverted scan set [^aeiou] on \"%s\": \"%s\"\n", text2, consonants);

    // 2. Field width and assignment suppression (*)
    int m = 0, d = 0, y = 0;
    const char* dateStr = "11-18-2012";
    // %*c discards the '-' delimiter regardless of whether it's '-' or '/'
    std::sscanf(dateStr, "%d%*c%d%*c%d", &m, &d, &y);
    std::printf("Date parsed: month = %d, day = %d, year = %d\n", m, d, y);

    // 3. Field width integer split
    int twoDigits = 0, rest = 0;
    const char* numStr = "123456";
    std::sscanf(numStr, "%2d%d", &twoDigits, &rest);
    std::printf("Split integer: %d and %d\n", twoDigits, rest);

    return 0;
}
